 internal static TextLayer TransformText(TextLayer t,Point origin,Point point,string kind,double initialAngle,double initialDistance){var size=SizeOf(t);var center=new Point(t.X+size.Width/2,t.Y+size.Height/2);if(kind=="move")return t with{X=t.X+point.X-origin.X,Y=t.Y+point.Y-origin.Y};if(kind=="resize"){var next=t with{Size=Math.Clamp(t.Size*(point-center).Length/Math.Max(1,initialDistance),4,2000)};var nextSize=SizeOf(next);return next with{X=center.X-nextSize.Width/2,Y=center.Y-nextSize.Height/2};}if(kind=="rotate")return t with{Angle=t.Angle+(Math.Atan2(point.Y-center.Y,point.X-center.X)-initialAngle)*180/Math.PI};return t;}
