 void TransformDocument(double angle,double sx,double sy){Remember();var m=new Matrix();m.Scale(sx,sy);m.Rotate(angle);var bounds=new MatrixTransform(m).TransformBounds(new Rect(0,0,source.PixelWidth,source.PixelHeight));m.Translate(-bounds.X,-bounds.Y);source=Imaging.Transform(source,angle,sx,sy);ink.Strokes.Transform(m,false);for(int i=0;i<texts.Count;i++){var t=texts[i];var size=SizeOf(t);var center=m.Transform(new Point(t.X+size.Width/2,t.Y+size.Height/2));texts[i]=t with{X=center.X-size.Width/2,Y=center.Y-size.Height/2,Angle=(sx*sy<0?-t.Angle:t.Angle)+angle};}crop=Rect.Empty;Refresh();}
 void Crop(){if(crop.IsEmpty||crop.Width<1||crop.Height<1){status.Text=L10n.T("CropHint");return;}Remember();int x=(int)crop.X,y=(int)crop.Y;var b=new CroppedBitmap(source,new Int32Rect(x,y,Math.Min((int)crop.Width,source.PixelWidth-x),Math.Min((int)crop.Height,source.PixelHeight-y)));b.Freeze();source=b;ink.Strokes.Transform(new Matrix(1,0,0,1,-x,-y),false);for(int i=0;i<texts.Count;i++)texts[i]=texts[i] with{X=texts[i].X-x,Y=texts[i].Y-y};crop=Rect.Empty;Refresh();}
